const missing=new Set([5,9,18,20,30,36,43]);
const S=(a,b=a)=>Array.from({length:b-a+1},(_,i)=>a+i).filter(n=>!missing.has(n)).map(n=>`b${String(n).padStart(5,"0")}`);
const row=(concept,bullets,sourceBlocks,image=null)=>({concept,bullets,sourceBlocks,...(image?{image}:{})});
const img=(path,caption,sourceCaption,cropBottomMm=null)=>({path,caption,sourceCaption,position:"after",size:"large",layout:"full_width",containsText:true,...(cropBottomMm?{cropBottomMm}:{})});
const I={
 indications:img("img/img_001.png","Interventions fréquemment réalisées sous sédation","Interventions fréquentes nécessitant une sédation hors bloc",8),
 depths:img("img/img_002.png","Continuum de profondeur de la sédation","Les différentes profondeurs de la sédation",8),
 continuum:img("img/img_003.png","Réponse et fonctions vitales selon la profondeur","Continuum de profondeur de la sédation de l’ASA",9),
 ramsay:img("img/img_004.png","Échelle de sédation de Ramsay modifiée","Échelle de sédation de Ramsay modifiée",9),
 assessment:img("img/img_005.png","Évaluation préprocédurale structurée","Évaluation et examen physique préprocéduraux",9),
 equipment:img("img/img_006.png","Matériel indispensable au lieu de sédation","Matériel nécessaire pour la sédation",10),
 drugs:img("img/img_007.png","Doses et propriétés des principaux agents","Médicaments de la sédation et doses utiles",12),
};




function buildFiche(){const parts=[
 {title:"Définir un objectif de sédation sûr",sections:[
  {title:"Indication et continuum",renderChunks:[1,2],rows:[
   row("Finalité procédurale",[{text:"Réduire inconfort, appréhension et souvenirs désagréables sans dépression cardiorespiratoire évitable.",children:["Une sédation adaptée augmente le succès et raccourcit parfois le geste","Elle protège également les soignants lors d’une procédure douloureuse ou anxiogène"]}],S(3,6),I.indications),
   row("Continuum imprévisible",["La profondeur s’étend de l’anxiolyse à l’anesthésie générale ; toute voie d’administration peut faire franchir un niveau.",{text:"Décider de la cible avant la première dose et préparer le sauvetage du niveau immédiatement supérieur.",children:["Plus la sédation est profonde, plus une complication majeure exige une réponse rapide"]}],S(7,10),I.depths),
   row("Contrat de sécurité",["Associer le confort recherché à une limite explicite de profondeur, un professionnel responsable et un plan de sauvetage immédiatement opérationnel."],S(6,7)),
  ]},
  {title:"Reconnaître la profondeur réelle",renderChunks:[3,2],rows:[
   row("Sédation minimale",["Réponse normale à la voix ; cognition ou coordination parfois altérées.","Ventilation, perméabilité aérienne et fonction cardiovasculaire conservées."],S(10,11)),
   row("Sédation modérée",[{text:"Réponse volontaire à la voix, seule ou accompagnée d’un contact tactile léger.",children:["Ventilation spontanée adéquate","Aucune manœuvre habituelle pour maintenir la voie aérienne","Fonction cardiovasculaire généralement maintenue"]}],S(12,14)),
   row("Sédation profonde",["Réponse uniquement après stimulations répétées ou douloureuses.","Obstruction et hypoventilation peuvent nécessiter une intervention ; la circulation reste souvent préservée."],S(15,15)),
   row("Anesthésie générale",["Aucune réponse même à la douleur ; fonctions respiratoire et cardiovasculaire souvent altérées."],S(16,16),I.continuum),
   row("Échelle commune",["Choisir une seule échelle institutionnelle, former tous les intervenants et documenter la tendance plutôt qu’un score isolé."],S(10,21),I.ramsay),
  ]},
 ]},
 {title:"Organiser la sécurité hors bloc",sections:[
  {title:"Équipe, gouvernance et compétences",rows:[
   row("Protocoles institutionnels",["Un comité de sédation harmonise indications, responsabilités, matériel, formation et critères de congé entre spécialités."],S(22,25)),
   row("Deux fonctions distinctes",[{text:"La personne qui administre et surveille la sédation ne réalise pas le geste technique.",children:["Elle reste au chevet sans interruption","Elle reconnaît une sédation trop profonde et sait intervenir","Un médecin doit être immédiatement disponible"]}],S(25,26)),
   row("Limite de compétence",["Une équipe non anesthésique formée prend en charge la sédation minimale à modérée.","Sédation profonde et anesthésie générale relèvent habituellement de l’anesthésiste."],S(26,26)),
  ]},
  {title:"Évaluation et jeûne",rows:[
   row("Évaluation préprocédurale",["Rechercher comorbidités, traitements, allergies, expériences antérieures, état hémodynamique et risque d’inhalation.",{text:"L’examen aérien anticipe ventilation et intubation difficiles.",children:["Prévoir le matériel et les compétences de sauvetage avant d’administrer le premier agent"]}],S(27,31),I.assessment),
   row("Jeûne de référence",[{text:"Pour sédation modérée ou profonde, appliquer les délais de l’anesthésie générale.",children:["Repas complet : 8 h","Repas léger : 6 h","Lait maternel : 4 h","Liquide clair : 2 h"]},"En urgence, pondérer profondeur nécessaire, comorbidités, risque d’inhalation et bénéfice du geste."],S(28,31)),
   row("Décision individualisée",["Un jeûne incomplet n’est ni anodin ni une interdiction automatique : la balance dépend du geste, de l’urgence, du terrain et de la profondeur nécessaire."],S(28,31)),
  ]},
  {title:"Surveillance, oxygène et réveil",rows:[
   row("Monitorage continu",["Mesurer pression artérielle, fréquence cardiaque et SpO₂ ; noter les valeurs initiales puis au moins toutes les 5 minutes.",{text:"Capnographie requise en sédation modérée ou profonde et à envisager à tous les niveaux.",children:["Elle détecte l’hypoventilation avant la désaturation sous oxygène"]},"Administrer de l’oxygène sauf contre-indication particulière."],S(32,32),I.equipment),
   row("Risque au réveil",["La fin de la stimulation révèle parfois une dépression respiratoire masquée pendant le geste.","Poursuivre surveillance, documentation et disponibilité d’une équipe formée jusqu’au congé."],S(33,38)),
   row("Congé objectivé",["Utiliser une échelle structurée telle qu’Aldrete et vérifier stabilité, ventilation, conscience, douleur, nausées et accompagnement."],S(38,38)),
  ]},
 ]},
 {title:"Titrer les hypnotiques et anxiolytiques",sections:[
  {title:"Benzodiazépines",rows:[
   row("Effets de classe",["Anxiolyse, sédation et amnésie ; préférer propofol ou dexmédétomidine à long terme en réanimation.","L’association aux opioïdes amplifie la dépression respiratoire."],S(48,51)),
   row("Midazolam IV",[{text:"Titrer selon indication, âge, foie, rein et coadministrations.",children:["Induction : 0,3–0,35 mg/kg, jusqu’à 0,6 mg/kg","Entretien : 0,015–0,06 mg/kg/h","Prémédication : 0,05–0,2 mg/kg"]}],S(50,56)),
   row("Voies alternatives",["IM : 0,07–0,08 mg/kg ; intranasal : 0,1 mg/kg chez l’adulte, action rapide sans voie IV.","PO : 0,25–0,5 mg/kg, maximum 20 mg ; adapter en insuffisance hépatique ou rénale."],S(52,56)),
   row("Pièges du midazolam",["Demi-vie 2–7 h ; prolongation possible chez l’obèse par redistribution.","Agitation paradoxale chez 1–2 % des enfants et parfois l’adulte : flumazénil possible.","Éviter injection intra-artérielle et extravasation ; la solution est acide."],S(55,56)),
   row("Lorazépam",["Demi-vie 12–18 h ; prémédication PO ou sublinguale 50 µg/kg, maximum 2–4 mg."],S(57,58)),
  ]},
  {title:"Propofol",rows:[
   row("Cinétique et titration",["Bolus ou perfusion IV, accumulation progressive imposant une diminution du débit.","Demi-vie biphasique : environ 40 min puis 4–7 h ; pas d’ajustement systématique hépatique ou rénal."],S(59,62)),
   row("Poids et terrain",[{text:"Chez l’obèse, calculer l’induction sur le poids maigre ; réévaluer la perfusion prolongée.",children:["Hypovolémie, sepsis et instabilité majorent fortement l’hypotension"]}],S(62,65)),
   row("Injection et formulation",["Émulsion lipidique à 10 % douloureuse ; lidocaïne possible sans dépasser 20 mg pour 200 mg de propofol.","Éviter les formulations à alcool benzylique chez le nouveau-né."],S(61,65)),
   row("PRIS",[{text:"Suspecter acidose métabolique, défaillance cardiaque, rhabdomyolyse et atteinte neurologique sous perfusion prolongée.",children:["Risque accru au-delà de 5 mg/kg/h ou 83 µg/kg/min pendant plus de 48 h","Corticoïdes, vasopresseurs et apport glucidique insuffisant ajoutent du risque"]}],S(45,65),I.drugs),
  ]},
 ]},
 {title:"Associer analgésie et dissociation",sections:[
  {title:"Opioïdes",rows:[
   row("Risque commun",["Bradypnée précède souvent l’apnée ; les associations sédatives potentialisent la dépression respiratoire.","Anticiper naloxone, ventilation et accumulation après doses répétées."],S(67,79)),
   row("Morphine",["Histaminolibération surtout si injection rapide ; métabolite actif accumulé en insuffisance rénale.","Dose IV habituelle : 0,1–0,2 mg/kg toutes les 4 h, à adapter à la tolérance."],S(68,72)),
   row("Fentanyl et dérivés",[{text:"Fentanyl IV 1–2 µg/kg, poids maigre chez l’obèse ; accumulation lors de réinjections.",children:["Sufentanil : environ dix fois plus puissant et peu cumulatif","Rémifentanil : estérases non spécifiques, demi-vie 3–4 min, perfusion 0,05–2 µg/kg/min"]}],S(73,84)),
   row("Rémifentanil à forte dose",["Au-delà de 0,2 µg/kg/min : hyperalgésie postopératoire possible.","Une injection rapide peut provoquer une rigidité thoracique gênant la ventilation."],S(82,84)),
  ]},
  {title:"Kétamine et agents inhalés",rows:[
   row("Dissociation utile",["Antagonisme NMDA avec activité AMPA conservée : anesthésie dissociative et analgésie.","Dose analgésique IV : 0,1–0,5 mg/kg ; induction IM : 4–10 mg/kg."],S(85,90)),
   row("Voies sans accès IV",["PO pédiatrique : 6–8 mg/kg ; intranasal : 3 mg/kg pour une procédure mineure.","Hypersécrétions : atropine ou glycopyrrolate ; cauchemars : une benzodiazépine peut aider."],S(91,94)),
   row("Protoxyde d’azote",["Analgésique-sédatif à concentration compatible avec l’oxygénation.","Sa diffusion rapide distend les cavités : éviter notamment pneumothorax et distension intestinale."],S(95,97)),
   row("Sévoflurane",["Son emploi correspond à une anesthésie générale et relève de l’anesthésiste."],S(98,99)),
  ]},
 ]},
 {title:"Choisir les adjuvants sans masquer la conscience",sections:[
  {title:"Dexmédétomidine",rows:[
   row("Sédation alpha-2",["Sédation, anxiolyse, analgésie et sympatholyse avec peu de dépression respiratoire.","Bolus IV 0,5–1 µg/kg sur 10 min ; perfusion 0,2–0,5 µg/kg/h, parfois jusqu’à 1."],S(100,105)),
   row("Hémodynamique",[{text:"Une administration rapide peut causer bradycardie sévère et hypotension.",children:["Prudence chez le sujet âgé ou cardiaque","Après perfusion prolongée, sevrer pour éviter hypertension, tachycardie, agitation et symptômes digestifs"]}],S(103,107)),
   row("Voie intranasale",["1–2 µg/kg si absence d’accès IV ; demi-vie moyenne proche de 3 h, élimination finale rénale."],S(107,107)),
  ]},
  {title:"Neuroleptiques et curarisation",rows:[
   row("Halopéridol",["Adjuvant du délire ou de l’agitation ; surveiller effets extrapyramidaux, parfois traités par diphenhydramine."],S(108,109)),
   row("Aucune sédation par le curare",[{text:"Un bloqueur neuromusculaire immobilise sans anesthésier, calmer ni analgésier.",children:["Garantir hypnotique et analgésie suffisants avant et pendant la paralysie","Surveiller le bloc par stimulateur nerveux"]}],S(110,113)),
   row("Usage prolongé",["Risque de polyneuropathie, majoré par les corticoïdes ; rocuronium et cisatracurium sont les agents cités."],S(110,113)),
   row("Lecture clinique",["L’absence de mouvement sous curare ne permet jamais d’évaluer la conscience, la douleur ni la profondeur anesthésique."],S(110,113)),
  ]},
 ]},
];
const sourceBlocks=[...new Set(parts.flatMap(p=>p.sections.flatMap(s=>s.rows.flatMap(r=>r.sourceBlocks))))];
return {matiere:"Anesthésie-Réanimation",title:"Anesthésie hors bloc: agents et techniques de sédation",year:"2026-2027",coverSubtitle:"Continuum, organisation, monitorage, médicaments et récupération",imageOmissions:[],sourceBlocks,parts,synthesis:{compactLayout:true,chiffres:{headers:["Repère","Valeur"],rows:[["Jeûne repas complet","8 h"],["Repas léger","6 h"],["Lait maternel","4 h"],["Liquide clair","2 h"],["Documentation","toutes les 5 min"],["PRIS","≥83 µg/kg/min >48 h"],["Rémifentanil","demi-vie 3–4 min"],["Dexmédétomidine IV","0,2–0,5 µg/kg/h"]]},tables:[{title:"Sauvetage selon la profondeur",headers:["Niveau","Point discriminant"],rows:[["Minimale","Réponse normale à la voix"],["Modérée","Réponse volontaire ; ventilation adéquate"],["Profonde","Réponse à la douleur ; voie aérienne parfois assistée"],["Générale","Aucune réponse ; fonctions vitales souvent altérées"]]},{title:"Choix pharmacologique",headers:["Besoin","Option et vigilance"],rows:[["Anxiolyse-amnésie","Midazolam ; dépression respiratoire synergique"],["Hypnose brève","Propofol ; hypotension et apnée"],["Analgésie-dissociation","Kétamine ; sécrétions et émergence"],["Sédation sans dépression respiratoire","Dexmédétomidine ; bradycardie et hypotension"],["Analgésie titrable","Opioïde ; bradypnée, accumulation ou rigidité"]]}],keyPoints:["La profondeur réelle peut dépasser l’objectif quelle que soit la voie utilisée.","Le professionnel de sédation ne réalise pas simultanément le geste.","Le sauvetage du niveau supérieur est préparé avant la première dose.","La capnographie est requise en sédation modérée ou profonde.","La fin de la stimulation est une période respiratoire à risque.","Les associations hypnotique-opioïde sont plus dépressives que chaque agent seul.","Le terrain et la durée modifient dose, cinétique et récupération.","Un curare n’apporte jamais ni sédation ni analgésie."],eclair:["Cible définie, sauvetage prêt.","Modérée : réponse volontaire, ventilation adéquate.","Profonde : réponse douloureuse, voie aérienne parfois assistée.","Jeûne 8–6–4–2 h selon l’apport.","PA, FC, SpO₂ et capnographie ; tracer toutes les 5 min.","Propofol : poids maigre chez l’obèse, hypotension si instable.","Midazolam + opioïde : synergie respiratoire.","Rémifentanil : très bref mais rigidité et hyperalgésie possibles.","Dexmédétomidine : peu de dépression respiratoire, bradycardie.","Curare : immobilité sans conscience ni analgésie."]}}}

const card=(recto,verso,sourceBlocks)=>({recto,verso,sourceBlocks});
function buildFlashcards(){const D=[
["Quel est le but d’une sédation procédurale ?","Réduire inconfort et souvenirs tout en minimisant la dépression cardiorespiratoire.",S(3,6)],
["Pourquoi planifier un niveau de sauvetage supérieur ?","La profondeur peut augmenter rapidement, quelle que soit la voie d’administration.",S(7,10)],
["Comment répond un patient en sédation minimale ?","Il répond normalement à la stimulation verbale.",S(10,11)],
["Quelles fonctions restent intactes en sédation minimale ?","Ventilation, voie aérienne et fonction cardiovasculaire.",S(10,11)],
["Comment répond un patient en sédation modérée ?","Volontairement à la voix, avec ou sans stimulation tactile légère.",S(12,14)],
["La voie aérienne requiert-elle une intervention en sédation modérée ?","Non, elle reste normalement perméable avec ventilation adéquate.",S(12,14)],
["Comment répond un patient en sédation profonde ?","Uniquement après stimulations répétées ou douloureuses.",S(15)],
["Quel risque aérien caractérise la sédation profonde ?","Obstruction et hypoventilation peuvent nécessiter une intervention.",S(15)],
["Comment répond un patient sous anesthésie générale ?","Il ne répond pas, même à une stimulation douloureuse.",S(16)],
["Pourquoi utiliser une échelle unique dans un service ?","Elle harmonise les décisions et réduit erreurs et événements graves.",S(10,21)],
["Quel dispositif institutionnel harmonise la sédation ?","Un comité de sédation multidisciplinaire.",S(22,25)],
["Qui doit être distinct de l’opérateur ?","La personne qui administre et surveille la sédation.",S(25,26)],
["Où reste le professionnel chargé de la sédation ?","En permanence au chevet du patient.",S(26)],
["Quelle compétence de secours est indispensable ?","Reconnaître et traiter une complication respiratoire de sursédation.",S(26)],
["Qui gère habituellement une sédation profonde ?","Un anesthésiste.",S(26)],
["Quel examen est central avant la sédation ?","L’évaluation des voies aériennes et de la difficulté de ventilation-intubation.",S(27)],
["Quel jeûne après un repas complet ?","8 heures pour une sédation modérée ou profonde.",S(28,31)],
["Quel jeûne après un repas léger ?","6 heures.",S(28,31)],
["Quel jeûne après du lait maternel ?","4 heures.",S(28,31)],
["Quel jeûne après un liquide clair ?","2 heures.",S(28,31)],
["Quels paramètres de base surveiller ?","Pression artérielle, fréquence cardiaque et SpO₂.",S(32)],
["À quelle fréquence documenter les constantes ?","Au moins toutes les 5 minutes pendant la sédation.",S(32)],
["Quand la capnographie est-elle requise ?","Pour toute sédation modérée ou profonde.",S(32)],
["Pourquoi la capnographie précède-t-elle la SpO₂ ?","Elle détecte l’hypoventilation avant la désaturation sous oxygène.",S(32)],
["Faut-il administrer de l’oxygène pendant la sédation ?","Oui, sauf contre-indication particulière.",S(32)],
["Pourquoi le réveil reste-t-il à risque respiratoire ?","La stimulation cesse alors qu’une sédation résiduelle persiste.",S(33,38)],
["Quelle échelle aide à décider du congé ?","L’échelle d’Aldrete.",S(38)],
["Quels effets recherchent les benzodiazépines ?","Anxiolyse, sédation et amnésie.",S(48,51)],
["Quel risque augmente avec benzodiazépine et opioïde ?","Une dépression respiratoire synergique.",S(50,56)],
["Quelle dose IV de midazolam pour une prémédication ?","0,05 à 0,2 mg/kg.",S(52,56)],
["Quelle dose IM adulte de midazolam ?","0,07 à 0,08 mg/kg.",S(52,56)],
["Quelle dose intranasale adulte de midazolam ?","0,1 mg/kg avec la solution à 5 mg/mL.",S(55)],
["Quelle dose orale de midazolam ?","0,25 à 0,5 mg/kg, maximum 20 mg.",S(56)],
["Quelle est la demi-vie du midazolam ?","2 à 7 heures, environ 3 heures en moyenne.",S(56)],
["Quels organes éliminent le midazolam ?","Métabolisme hépatique puis excrétion rénale.",S(56)],
["Quel effet paradoxal du midazolam peut survenir ?","Une agitation, surtout chez l’enfant, parfois réversible par flumazénil.",S(56)],
["Quelle est la demi-vie du lorazépam ?","12 à 18 heures.",S(57,58)],
["Quelle dose de lorazépam en prémédication ?","50 µg/kg PO ou sublingual, maximum 2 à 4 mg.",S(57,58)],
["Dans quel véhicule est formulé le propofol ?","Une émulsion lipidique contenant 10 % d’Intralipide.",S(59,61)],
["Pourquoi réduire progressivement une perfusion de propofol ?","L’agent s’accumule avec le temps.",S(62)],
["Faut-il ajuster systématiquement le propofol au rein ?","Non, aucun ajustement rénal systématique n’est nécessaire.",S(62)],
["Quel poids utiliser pour l’induction de l’obèse au propofol ?","Le poids maigre estimé.",S(62)],
["Quels terrains majorent l’hypotension au propofol ?","Hypovolémie, instabilité hémodynamique et sepsis.",S(65)],
["Comment réduire la douleur d’injection du propofol ?","Lidocaïne, prétraitement veineux ou massage pendant l’injection.",S(61)],
["Quelle limite de lidocaïne avec 200 mg de propofol ?","20 mg pour éviter l’instabilité de l’émulsion lipidique.",S(61)],
["Quels signes composent le PRIS ?","Acidose, défaillance cardiaque, rhabdomyolyse et atteinte neurologique.",S(45,60)],
["Quel débit prolongé augmente le risque de PRIS ?","Plus de 83 µg/kg/min ou 5 mg/kg/h pendant plus de 48 h.",S(45,60)],
["Quels cofacteurs favorisent le PRIS ?","Corticoïdes, vasopresseurs, état critique et apport glucidique insuffisant.",S(60)],
["Quel signe précède souvent l’apnée sous morphine ?","La bradypnée.",S(68,72)],
["Pourquoi la morphine s’accumule-t-elle en insuffisance rénale ?","Son métabolite actif est principalement éliminé par le rein.",S(68,72)],
["Quelle dose IV habituelle de morphine est citée ?","0,1 à 0,2 mg/kg toutes les 4 heures, adaptée au patient.",S(72)],
["Quel avantage a l’hydromorphone sur la morphine ?","Moins d’histaminolibération et une alternative en cas d’allergie.",S(73,74)],
["Quelle dose IV initiale de fentanyl est citée ?","1 à 2 µg/kg.",S(75,79)],
["Pourquoi le fentanyl s’accumule-t-il ?","Les doses répétées saturent sa distribution rapide.",S(75,79)],
["Quel antagoniste inverse la dépression respiratoire opioïde ?","La naloxone.",S(75,79)],
["Quel poids utiliser pour le fentanyl chez l’obèse ?","Le poids maigre pour les administrations initiales.",S(79)],
["Quelle puissance relative possède le sufentanil ?","Environ dix fois celle du fentanyl.",S(80,81)],
["Pourquoi le rémifentanil agit-il très brièvement ?","Il est hydrolysé par des estérases plasmatiques et tissulaires non spécifiques.",S(82,84)],
["Quelle est la demi-vie du rémifentanil ?","Environ 3 à 4 minutes.",S(82,84)],
["Quelle perfusion de rémifentanil est citée ?","0,05 à 2 µg/kg/min.",S(82,84)],
["À partir de quel débit l’hyperalgésie est-elle signalée ?","Au-dessus de 0,2 µg/kg/min.",S(84)],
["Quelle complication ventilatoire suit une injection rapide de rémifentanil ?","Une rigidité thoracique transitoire.",S(84)],
["Sur quel récepteur agit surtout la kétamine ?","Antagoniste du récepteur NMDA du glutamate.",S(85,86)],
["Quels deux effets majeurs possède la kétamine ?","Anesthésie dissociative et analgésie.",S(85,86)],
["Quelle dose analgésique IV de kétamine ?","0,1 à 0,5 mg/kg.",S(88,90)],
["Quelle dose d’induction IM de kétamine ?","4 à 10 mg/kg.",S(90)],
["Quelle dose intranasale de kétamine ?","3 mg/kg pour prémédication ou procédure mineure.",S(93,94)],
["Quel anticholinergique réduit les sécrétions sous kétamine ?","Atropine ou glycopyrrolate.",S(93,94)],
["Comment réduire les cauchemars d’émergence de la kétamine ?","Une benzodiazépine peut être associée.",S(93,94)],
["Pourquoi éviter le N₂O dans un pneumothorax ?","Il diffuse dans la cavité et en augmente le volume.",S(95,97)],
["Quel usage simple peut convenir au N₂O ?","Réduction de fracture, pose de voie veineuse ou procédure brève.",S(95,97)],
["Qui doit administrer le sévoflurane hors bloc ?","Un anesthésiste, car il s’agit d’une anesthésie générale.",S(98,99)],
["Quel récepteur cible la dexmédétomidine ?","Le récepteur alpha-2 adrénergique.",S(100,101)],
["Quels effets associe la dexmédétomidine ?","Sédation, analgésie, anxiolyse et sympatholyse.",S(100,101)],
["La dexmédétomidine déprime-t-elle la respiration ?","Elle provoque peu ou pas de dépression respiratoire.",S(107)],
["Quel bolus IV de dexmédétomidine est cité ?","0,5 à 1 µg/kg sur environ 10 minutes.",S(102,104)],
["Quelle perfusion usuelle de dexmédétomidine ?","0,2 à 0,5 µg/kg/h, parfois jusqu’à 1 µg/kg/h.",S(105)],
["Quelle dose intranasale de dexmédétomidine ?","1 à 2 µg/kg sans accès intraveineux.",S(107)],
["Quel danger suit une administration alpha-2 rapide ?","Bradycardie sévère et hypotension.",S(107)],
["Quels signes annoncent un sevrage de dexmédétomidine ?","HTA, tachycardie, agitation, céphalées, nausées et vomissements.",S(106,107)],
["Pourquoi être prudent avec la dexmédétomidine en gériatrie ?","La bradycardie et l’hypotension sont moins bien tolérées.",S(107)],
["Quel neuroleptique IV peut aider au délire ?","L’halopéridol.",S(108,109)],
["Quel effet indésirable surveiller sous halopéridol ?","Les effets extrapyramidaux.",S(108,109)],
["Que traite parfois la diphenhydramine avec l’halopéridol ?","Les manifestations extrapyramidales.",S(108,109)],
["Un curare possède-t-il une propriété sédative ?","Non, il immobilise sans modifier la conscience.",S(110,113)],
["Un curare possède-t-il une propriété analgésique ?","Non, une analgésie indépendante est indispensable.",S(110,113)],
["Quel outil surveille la curarisation ?","Un stimulateur nerveux périphérique.",S(110,113)],
["Quel facteur augmente la polyneuropathie sous curare prolongé ?","L’association à des corticoïdes.",S(110,113)],
["Quels curares sont cités pour l’usage prolongé ?","Rocuronium et cisatracurium.",S(110,113)],
["Quel principe résume le choix d’un sédatif ?","Adapter l’agent à l’hémodynamique, l’âge, le geste et la récupération souhaitée.",S(114,120)],
["Pourquoi une voie non IV ne protège-t-elle pas d’une sursédation ?","Toute voie peut entraîner un passage imprévu vers une profondeur supérieure.",S(7)],
["Que doit contenir le chariot de sédation ?","Oxygène, aspiration, ventilation, voie aérienne, urgence et antagonistes.",S(32,37)],
["Pourquoi noter des valeurs préprocédurales ?","Elles servent de référence pour reconnaître une dégradation liée à la sédation.",S(32)],
["Quel signal impose d’arrêter la titration ?","Une profondeur supérieure à la cible ou une altération ventilatoire-hémodynamique.",S(7,16)],
["Pourquoi éviter une dose standard chez tous les patients ?","Âge, comorbidités, interactions et durée modifient fortement la réponse.",S(39,47)],
["Quel patient est particulièrement sensible au propofol ?","Le patient hypovolémique, septique ou hémodynamiquement instable.",S(63,65)],
["Pourquoi anticiper le congé accompagné ?","Une sédation résiduelle altère encore vigilance, coordination et ventilation.",S(33,38)],
["Quel événement doit être documenté pendant la récupération ?","Toute désaturation, obstruction, intervention aérienne ou antagonisation.",S(33,38)],
["Quel principe s’applique aux allergies œuf-soya et propofol ?","L’absence d’anaphylaxie antérieure permet souvent son utilisation prudente.",S(63,64)],
["Quelle voie de morphine est déconseillée en répétition ?","La voie intramusculaire.",S(68,72)],
["Pourquoi la voie SC de morphine reste-t-elle utile ?","Elle évite une perfusion IV, notamment en soins palliatifs.",S(69,72)],
["Quel mécanisme rend le N₂O dangereux dans une cavité close ?","Sa diffusion plus rapide que l’azote augmente le volume ou la pression.",S(95,97)],
["Quand sevrer progressivement la dexmédétomidine ?","Après une perfusion prolongée afin d’éviter un rebond sympathique.",S(106,107)],
];return D.map(([recto,verso,sourceBlocks])=>card(recto,verso,sourceBlocks))}

const T=(e,j)=>[true,e,j],F=(e,j)=>[false,e,j];
const qcm=(enonce,sourceBlocks,correction_generale,items,newInformation=null)=>({enonce:newInformation?`${newInformation} ${enonce}`:enonce,format:"qcm",sourceBlocks,correction_generale,...(newInformation?{newInformation}:{}),items:items.map(([is_correct,enonce,justification],i)=>({lettre:"ABCDE"[i],enonce,is_correct,justification:justification.length<35?`${justification} ${correction_generale}`:justification}))});
const qroc=(enonce,reponse_attendue,sourceBlocks,correction_generale,newInformation=null)=>({enonce:newInformation?`${newInformation} ${enonce}`:enonce,format:"qroc",reponse_attendue,items:[],sourceBlocks,correction_generale,...(newInformation?{newInformation}:{})});

