function validateSourceBlocks(extract,content){const valid=new Set((extract.blocs||[]).filter(b=>b.id).map(b=>b.id));const visit=value=>{if(!value||typeof value!=="object")return;if(Array.isArray(value)){value.forEach(visit);return;}if(value.sourceBlocks)for(const id of value.sourceBlocks)if(!valid.has(id))throw new Error(`sourceBlock absent: ${id}`);Object.values(value).forEach(visit)};visit(content)}
export function buildChapter31(extract){const fiche=buildFiche(),flashcards=buildFlashcards(),series=[...buildIq(),...buildDq(),...buildIr(),...buildDr()];const result={fiche,flashcards,series};validateSourceBlocks(extract,result);return result}
export default buildChapter31;
